import { useRouter } from 'vue-router'

export function useNavigate() {
  const router = useRouter()

  /**
   * 通用跳转方法
   * @param {string | object} options - 路径字符串 或 配置对象
   * @param {string} [options.path] - 跳转路径
   * @param {object} [options.query] - 路由参数
   * @param {boolean} [options.replace=false] - 是否替换当前历史记录
   * @param {boolean} [options.newTab=false] - 是否在新窗口打开
   */
  const navigate = (options) => {
    let path = ''
    let query = {}
    let replace = false
    let newTab = false

    // 1. 参数归一化处理
    if (typeof options === 'string') {
      path = options
    } else if (typeof options === 'object' && options !== null) {
      path = options.path || ''
      query = options.query || {}
      replace = options.replace || false
      newTab = options.newTab || false
    }

    // 防止空路径报错
    if (!path) {
      console.warn('navigate: path is required')
      return
    }

    // 2. 判断是否是外部链接 (http/https/mailto/tel 开头)
    const isExternal = /^(http|https|mailto|tel):/.test(path)

    // 3. 执行跳转逻辑
    if (isExternal) {
      if (newTab) {
        window.open(path, '_blank')
      } else {
        window.location.href = path
      }
      return
    }

    // 4. 内部路由跳转
    if (newTab) {
      // 内部路由如果要新窗口打开，需要解析出完整的 href
      const routeData = router.resolve({ path, query })
      window.open(routeData.href, '_blank')
    } else {
      // 普通内部跳转
      if (replace) {
        router.replace({ path, query })
      } else {
        router.push({ path, query })
      }
    }
  }

  return {
    navigate
  }
}