<template>
	<div class="header_warp">
		<div class="header_bg"></div>
		<div class="left_mune" @click="handleNavigate('/welcome')"></div>

		<div class="top-nav">
			<div v-for="item in menuList" :key="item.path" class="nav-item" :class="[
				item.className,
				{ active_item: activeTab === item.path }
			]" :style="item.style" @click="handleNavigate(item.path)">
				{{ item.name }}
			</div>
		</div>
		<div class="logout_btn" @click="handleLogout">退出</div>
	</div>
</template>

<script setup>
import { useNavigate } from '@/hooks/useNavigate'
import { logout } from '@/utils/auth'
import { ref, watch } from 'vue'
import { useRoute } from 'vue-router'

const route = useRoute()
const { navigate } = useNavigate()
const activeTab = ref('')

// 定义导航配置列表 (将样式和路径逻辑分离)
const menuList = [
	{ name: '项目总览', path: '/page/xmzl' },
	{ name: '顶进组合管幕', path: '/page/zlzh' },
	{ name: '支护结构一体化施工', path: '/page/zhzh', style: { width: '210px' } },
	{ name: '上下层开挖', path: '/page/sxtjkw' },
	{ name: '多圆组合管幕', path: '/page/dyzhgm', className: 'spcolor' },
	{ name: '并行建造台车', path: '/page/bxjztc', className: 'spcolor' },
	{ name: '始发接收台车', path: '/page/sfjstc', className: 'spcolor' },
	// { name: '装载机', path: '/page/zzj', className: 'spcolor' },

]

// 统一跳转处理
const handleNavigate = (path) => {
	// 立即设置高亮（提升点击响应速度体验）
	activeTab.value = path
	navigate(path)
}

const handleLogout = () => {
	logout()
	navigate('/login')
}

/**
 * 核心修复点：
 * 1. 使用 Getter 函数 () => route.path 来监听路由变化
 * 2. 添加 { immediate: true } 选项，确保组件刚加载(刷新)时也会执行一次，
 * 这样就不需要单独写 activeTab.value = route.path 了
 */
watch(
	() => route.path,
	(newPath) => {
		console.log('路由变化:', newPath)
		// 只有当新路径在我们的菜单列表中时，才更新高亮，防止跳到详情页时高亮消失
		// 如果你的逻辑是“子路由也要高亮父级”，可以使用 newPath.startsWith(item.path)
		if (newPath) {
			activeTab.value = newPath
		}
	},
	{ immediate: true }
)
</script>

<style scoped lang="less">
.header_warp {
	position: relative;

	.left_mune {
		position: absolute;
		top: 0;
		left: 0;
		bottom: 0;
		width: 240px;
		z-index: 10;
		cursor: pointer;
	}

	.header_bg {
		height: 75px;
		background: url('@/assets/images/top_title.png');
		background-size: contain;
		background-repeat: no-repeat;
		background-position: center;
	}

	// 顶部导航
	.top-nav {
		position: absolute;
		bottom: 0;
		right: 118px;
		display: flex;
		justify-content: center;
		align-items: center;
		height: 50px;
		border-bottom: 2px solid rgba(72, 237, 252, 0.3);
		gap: 5px;
		padding: 0 20px;

		.nav-item {
			padding: 6px 16px;
			height: 50px;
			min-width: 130px;
			line-height: 50px;
			font-size: 18px;
			text-align: left;
			color: rgba(255, 255, 255, 0.7);
			cursor: pointer;
			position: relative;
			text-align: center;
			transition: all 0.3s;
			background-size: cover;
			// 默认背景（蓝色系）
			background-image: url("@/assets/images/-s-nav_zonglan.png");
			background-size: 100% 100%;

			&:hover,
			&.active_item {
				color: #fff;
				background-image: url("@/assets/images/nav_zonglan_ac@2x.png");
				background-size: 100% 100%;
			}
		}

		// 特殊颜色样式（spcolor）
		.nav-item.spcolor {
			background-image: url("@/assets/images/nav_dy@2x.png");
			background-size: 100% 100%;

			&:hover,
			&.active_item {
				color: #fff;
				background-image: url("@/assets/images/-s-nav_dy_ac.png");
				background-size: 100% 100%;
			}
		}
	}

	.logout_btn {
		position: absolute;
		top: 32px;
		right: 28px;
		z-index: 12;
		min-width: 76px;
		height: 30px;
		line-height: 30px;
		text-align: center;
		cursor: pointer;
		color: #73fdff;
		font-size: 14px;
		font-family: "SourceHanSansSC 微软雅黑";
		background: rgba(9, 49, 92, 0.72);
		border: 1px solid rgba(72, 237, 252, 0.48);
		box-shadow: inset 0 0 16px rgba(72, 237, 252, 0.12);
	}

	.logout_btn:hover {
		color: #fff;
		border-color: rgba(115, 253, 255, 0.9);
	}
}
</style>
